import { readFileSync } from 'fs'
import { join } from 'path'
import { db, schema } from '@/db'
import { EMBEDDING_MODEL, isCurrentDimension } from '@/lib/embeddings/model'
import { bufferToEmbedding } from './embedding'
import { parseTaxonomyFiles, type TaxonomyIndex } from './taxonomy-embedding'

/**
 * Topic taxonomy for labeling flowchart clusters.
 *
 * In production, the taxonomy is stored in the database (`topic_taxonomy` table)
 * and can be regenerated via the admin panel.
 *
 * The taxonomy falls back to static files generated by
 * `scripts/generateTopicTaxonomy.ts` when the database has no rows written by the
 * current embedding model (empty, or still holding vectors from an older model
 * awaiting re-embedding). Vectors from two models are never mixed.
 *
 * At runtime, the browse API loads the taxonomy once and includes all label
 * embeddings in the distance matrix alongside flowchart embeddings. The client
 * then assigns the nearest label to each cluster.
 */

export interface Taxonomy {
  labels: string[]
  embeddings: Float32Array[]
  breadths: number[]
}

const LABEL_PREFIX = 'label:'

/**
 * How long a replica trusts its copy. clearTaxonomyCache() only reaches the
 * replica that regenerated or re-embedded the taxonomy; the others pick the change
 * up within this window.
 */
export const TAXONOMY_CACHE_TTL_MS = 60_000

let cachedTaxonomy: { value: Taxonomy; loadedAt: number } | null = null

/**
 * Clear the taxonomy cache. Call this after regenerating the taxonomy.
 */
export function clearTaxonomyCache(): void {
  cachedTaxonomy = null
}

/**
 * Load the topic taxonomy from database (preferred) or disk (fallback).
 * Cached for TAXONOMY_CACHE_TTL_MS.
 */
export async function loadTaxonomy(): Promise<Taxonomy> {
  if (cachedTaxonomy && Date.now() - cachedTaxonomy.loadedAt < TAXONOMY_CACHE_TTL_MS) {
    return cachedTaxonomy.value
  }

  // Try loading from database first; fall back to files (for development, an
  // empty DB, or rows still awaiting re-embedding)
  const value = (await loadTaxonomyFromDb()) ?? loadTaxonomyFromFiles()
  cachedTaxonomy = { value, loadedAt: Date.now() }
  return value
}

/**
 * Load taxonomy from database.
 * Returns null unless every row was embedded by the current model (a partly
 * re-embedded table must not mix vector spaces).
 */
async function loadTaxonomyFromDb(): Promise<Taxonomy | null> {
  const rows = await db.select().from(schema.topicTaxonomy)

  if (rows.length === 0) {
    return null
  }

  const current = rows.every(
    (row) => row.embeddingModel === EMBEDDING_MODEL && isCurrentDimension(row.embedding)
  )
  if (!current) {
    console.warn(
      `[taxonomy] topic_taxonomy rows are not all ${EMBEDDING_MODEL}; using the static files until they are re-embedded`
    )
    return null
  }

  const labels: string[] = []
  const embeddings: Float32Array[] = []
  const breadths: number[] = []

  for (const row of rows) {
    labels.push(row.label)
    embeddings.push(bufferToEmbedding(row.embedding))
    breadths.push(row.breadth ?? 0) // Default to 0 if not set (legacy data)
  }

  return { labels, embeddings, breadths }
}

/**
 * Load taxonomy from static files: `topic-taxonomy.json` (label index, model id,
 * breadths) and `topic-taxonomy.bin` (packed Float32 vectors). Throws if the
 * files were written by a different model.
 */
function loadTaxonomyFromFiles(): Taxonomy {
  const dir = join(process.cwd(), 'src/lib/flowcharts')
  const index: TaxonomyIndex = JSON.parse(readFileSync(join(dir, 'topic-taxonomy.json'), 'utf-8'))
  const bin = readFileSync(join(dir, 'topic-taxonomy.bin'))
  return parseTaxonomyFiles(index, bin)
}

/** Build a label ID from a label string (e.g. "label:Fraction Arithmetic") */
export function labelId(label: string): string {
  return `${LABEL_PREFIX}${label}`
}

/** Check if an ID is a taxonomy label ID */
export function isLabelId(id: string): boolean {
  return id.startsWith(LABEL_PREFIX)
}

/** Extract the label text from a label ID */
export function labelFromId(id: string): string {
  return id.slice(LABEL_PREFIX.length)
}
